#!/usr/bin/env node
// Expands the Italian, Brazilian Portuguese and German learning routes with
// contextual Reading, Vocabulary and Grammar lessons through B1.  Kept as a
// deterministic authoring script: the seed remains the single curriculum
// source and src/worlds/* is regenerated by sync-worlds-from-seed.js.
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const lessonsPath = path.join(ROOT, 'lib', 'seed-lessons.json');
const unitsPath = path.join(ROOT, 'lib', 'seed-units.json');
const lessons = require(lessonsPath);
const units = require(unitsPath);

// Remove superseded flat prototype lessons before expanding the canonical
// 12-unit routes. Without this cleanup Italian B1 and German A1-B1 expose a
// duplicate thirteenth Reading with no unit association.
for (let index = lessons.length - 1; index >= 0; index -= 1) {
  const row = lessons[index];
  if (
    ['italian', 'portuguese', 'german'].includes(row.target_language) &&
    ['A1', 'A2', 'B1'].includes(row.level) &&
    !row.unit_slug
  ) {
    lessons.splice(index, 1);
  }
}

