// Italian B1 now follows the same complete connected route as Portuguese and
// German. Its Listening lesson is kept as authored for the later audio pass.

function sentence(language, words, level, title) {
  const [a, b, c] = words;
  if (language === 'italian') return `Nel tema «${title}», un piccolo gruppo della comunità parla di ${a}, ${b} e ${c}. Ogni persona racconta un'esperienza, ascolta gli altri e propone una soluzione concreta. Alla fine decidono di collaborare perché un obiettivo chiaro rende più facile migliorare la vita quotidiana.`;
  if (language === 'portuguese') return `No tema «${title}», um pequeno grupo da comunidade conversa sobre ${a}, ${b} e ${c}. Cada pessoa conta uma experiência, escuta as outras e propõe uma solução concreta. No final, decidem colaborar porque um objetivo claro ajuda a melhorar a vida cotidiana.`;
  return `Im Thema „${title}“ spricht eine kleine Gruppe aus der Gemeinschaft über ${a}, ${b} und ${c}. Jede Person erzählt von einer Erfahrung, hört den anderen zu und schlägt eine konkrete Lösung vor. Am Ende entscheiden sie sich für Zusammenarbeit, weil ein klares Ziel den Alltag verbessern kann.`;
}

function grammarPrompt(language, level, words) {
  const word = words[0];
  if (language === 'italian') return { prompt: `Quale frase usa «${word}» in modo corretto?`, options: [`Il gruppo parla di ${word}.`, `Il gruppo ${word} parla di.`, `${word} il di gruppo parla.`, `Parla gruppo il ${word} di.`] };
  if (language === 'portuguese') return { prompt: `Qual frase usa «${word}» corretamente?`, options: [`O grupo fala sobre ${word}.`, `O grupo ${word} fala sobre.`, `${word} o sobre grupo fala.`, `Fala grupo o ${word} sobre.`] };
  return { prompt: `Welcher Satz verwendet „${word}“ richtig?`, options: [`Die Gruppe spricht über ${word}.`, `Die Gruppe ${word} spricht über.`, `${word} die über Gruppe spricht.`, `Spricht Gruppe die ${word} über.`] };
}

function makeLesson(language, level, unit, skill, order) {
  const [slug, title, objective, vocabularyLine] = unit;
  const words = vocabularyLine.split(', ');
  const readingText = sentence(language, words, level, title);
  const unitNumber = Math.floor(order / 10);
  const freeUnitLimit = level === 'A1' ? 3 : level === 'A2' ? 2 : 1;
  const isFree = unitNumber <= freeUnitLimit;
  const base = {
    slug: `${language}-${level.toLowerCase()}-${slug}-${skill}`,
    target_language: language, level, skill, unit_slug: slug,
    title: `${title}: ${skill === 'reading' ? 'lectura' : skill === 'grammar' ? (language === 'portuguese' ? 'gramática' : language === 'italian' ? 'grammatica' : 'Grammatik') : (language === 'portuguese' ? 'palavras' : language === 'italian' ? 'parole' : 'Wortschatz')}`,
    description: objective, order_index: order, estimated_minutes: skill === 'reading' ? 12 : 10,
    is_free: isFree, access_tier: isFree ? 'free' : 'premium', payment_price_usd: 4.99
  };
  const content = {
    language: courses[language].label, language_key: language, level_title: `${courses[language].label} ${level}`,
    intro: objective, mission: objective,
    grammar: level === 'A1' ? 'Frases afirmativas, preguntas simples y vocabulario básico.' : level === 'A2' ? 'Presente, pasado cotidiano, conectores y expresiones funcionales.' : 'Conectores, contraste, opinión justificada y estructuras para explicar causas y consecuencias.',
    phrases: words.slice(0, 4).map((word) => language === 'german' ? `Wir lernen: ${word}.` : language === 'italian' ? `Impariamo: ${word}.` : `Aprendemos: ${word}.`),
    vocabulary: words.map((word, index) => ({ word, translation: `Palabra clave ${index + 1}`, example: language === 'german' ? `Ich benutze das Wort „${word}“ im Kontext.` : language === 'italian' ? `Uso la parola «${word}» nel contesto.` : `Uso a palavra «${word}» no contexto.` })),
    xp_reward: 25,
    access_policy: { free_lessons_per_level: freeUnitLimit, is_free_preview: isFree, premium_price_usd: 4.99, premium_label: 'Premium desbloquea la ruta completa' }
  };
  if (skill === 'reading') {
    content.reading = { text: readingText, questions: [
      language === 'german' ? 'Worüber spricht die Gruppe?' : language === 'italian' ? 'Di che cosa parla il gruppo?' : 'Sobre o que o grupo conversa?',
      language === 'german' ? 'Was macht jede Person?' : language === 'italian' ? 'Che cosa fa ogni persona?' : 'O que cada pessoa faz?',
      language === 'german' ? 'Warum arbeiten sie zusammen?' : language === 'italian' ? 'Perché decidono di collaborare?' : 'Por que decidem colaborar?',
      language === 'german' ? 'Welche Idee hilft im Alltag?' : language === 'italian' ? 'Quale idea aiuta nella vita quotidiana?' : 'Que ideia ajuda na vida cotidiana?'
    ] };
    const readingOptions = language === 'german'
      ? [
          ['Erzählt von einer Erfahrung, hört zu und schlägt eine Lösung vor.', 'Kauft eine Eintrittskarte für eine Veranstaltung.', 'Hört den anderen Personen nicht zu.', 'Sagt das Projekt ab.'],
          ['Weil sie ein klares Ziel haben.', 'Weil sie keine Zeit haben.', 'Weil sie das Thema nicht kennen.', 'Weil sie lieber allein arbeiten.'],
          ['Eine konkrete Lösung, die gemeinsam umgesetzt wird.', 'Eine Liste ohne Zusammenhang.', 'Eine Diskussion ohne Ziel.', 'Eine Entscheidung von nur einer Person.']
        ]
      : language === 'italian'
        ? [
            ['Racconta un’esperienza, ascolta e propone una soluzione.', 'Compra un biglietto per un evento.', 'Non ascolta le altre persone.', 'Annulla il progetto.'],
            ['Perché hanno un obiettivo chiaro.', 'Perché non hanno tempo.', 'Perché non conoscono il tema.', 'Perché preferiscono lavorare da soli.'],
            ['Una soluzione concreta e collaborativa.', 'Un elenco senza contesto.', 'Una discussione senza obiettivo.', 'Una decisione individuale.']
          ]
        : [
            ['Conta uma experiência, escuta e propõe uma solução.', 'Compra um ingresso para um evento.', 'Não escuta as outras pessoas.', 'Cancela o projeto.'],
            ['Porque têm um objetivo claro.', 'Porque não têm tempo.', 'Porque não conhecem o tema.', 'Porque preferem trabalhar sozinhos.'],
            ['Uma solução concreta e colaborativa.', 'Uma lista sem contexto.', 'Uma discussão sem objetivo.', 'Uma decisão individual.']
          ];
    content.exercises = [
      { type: 'mcq', prompt: content.reading.questions[0], options: [words[0], words[7], words[8], words[9]], answer: 0 },
      { type: 'mcq', prompt: content.reading.questions[1], options: readingOptions[0], answer: 0 },
      { type: 'mcq', prompt: content.reading.questions[2], options: readingOptions[1], answer: 0 },
      { type: 'mcq', prompt: content.reading.questions[3], options: readingOptions[2], answer: 0 }
    ];
  } else if (skill === 'listening') {
    content.transcript = `${readingText} ${language === 'german' ? 'Danach fasst die Gruppe die wichtigsten Ideen zusammen.' : language === 'italian' ? 'Poi il gruppo riassume le idee più importanti.' : 'Depois, o grupo resume as ideias mais importantes.'}`;
    content.listeningType = 'monologue';
    content.dictationSegments = [readingText.split('. ')[0]];
    content.exercises = [{ type: 'mcq', prompt: language === 'german' ? 'Worum geht es in der Aufnahme?' : language === 'italian' ? 'Di che cosa parla la registrazione?' : 'Sobre o que fala a gravação?', options: [objective, words[4], words[5], words[6]], answer: 0 }];
  } else if (skill === 'speaking') {
    content.dialogue = [
      { speaker: 'A', line: language === 'german' ? `Ich möchte ${objective}. Kannst du mir helfen?` : language === 'italian' ? `Vorrei ${objective}. Puoi aiutarmi?` : `Eu quero ${objective}. Você pode me ajudar?` },
      { speaker: 'B', line: language === 'german' ? 'Ja, gern. Lass uns Schritt für Schritt sprechen.' : language === 'italian' ? 'Sì, certo. Parliamone passo dopo passo.' : 'Claro. Vamos falar passo a passo.' }
    ];
    content.exercises = [{ type: 'practice', prompt: language === 'german' ? 'Sprich zwei Sätze über diese Situation.' : language === 'italian' ? 'Di due frasi su questa situazione.' : 'Fale duas frases sobre esta situação.' }];
  } else if (skill === 'writing') {
    content.assignment = language === 'german' ? `Schreibe 4 bis 6 Sätze: ${objective}.` : language === 'italian' ? `Scrivi da 4 a 6 frasi per ${objective}.` : `Escreva de 4 a 6 frases para ${objective}.`;
    content.criteria = [language === 'german' ? 'klare Idee' : language === 'italian' ? 'idea chiara' : 'ideia clara', language === 'german' ? 'passender Wortschatz' : language === 'italian' ? 'vocabolario adatto' : 'vocabulário adequado'];
    content.exercises = [{ type: 'practice', prompt: content.assignment }];
  } else if (skill === 'grammar') {
    const exercise = grammarPrompt(language, level, words);
    content.exercises = [0, 1, 2, 3, 4].map((offset) => {
      const word = words[offset]; const item = grammarPrompt(language, level, [word]);
      const shuffled = [...item.options]; const correct = offset % 4;
      [shuffled[0], shuffled[correct]] = [shuffled[correct], shuffled[0]];
      return { type: 'mcq', prompt: item.prompt, options: shuffled, answer: correct === 0 ? 0 : correct };
    });
  } else {
    content.exercises = words.slice(0, 6).map((word, index) => {
      const correct = index % 4;
      const options = [word, words[(index + 1) % words.length], words[(index + 2) % words.length], words[(index + 3) % words.length]];
      [options[0], options[correct]] = [options[correct], options[0]];
      return { type: 'mcq', prompt: `Selecciona la palabra trabajada en esta unidad:`, options, answer: correct };
    });
  }
  base.content_json = content;
  return base;
}

