let addedUnits = 0; let addedLessons = 0;
for (const [language, course] of Object.entries(courses)) {
  for (const [level, courseUnits] of Object.entries(course.levels)) {
    courseUnits.forEach((unit, index) => {
      const [slug, title, objective, vocabulary] = unit;
      if (!units.some((item) => item.target_language === language && item.slug === slug)) {
        units.push({ slug, target_language: language, level, title, title_es: objective, description: objective, order_index: index + 1, unit_overview: { objective, outcomes: [objective, 'comprender un texto contextual', 'usar vocabulario en un reto'], grammar: [level === 'A1' ? 'frases básicas' : level === 'A2' ? 'pasado y conectores' : 'opinión y conectores'], vocabulary: vocabulary.split(', ').slice(0, 6), scenario: title } });
        addedUnits += 1;
      }
      // A route must expose the same connected learning sequence in every
      // supported language. These activities are independent practice, not
      // questions that require recalling the Reading text.
      const routeSkills = ['reading', 'listening', 'speaking', 'grammar', 'vocabulary', 'writing'];
      routeSkills.forEach((skill, skillIndex) => {
        const slugWithSkill = `${language}-${level.toLowerCase()}-${slug}-${skill}`;
        const authoredLesson = makeLesson(language, level, unit, skill, (index + 1) * 10 + skillIndex);
        const existingLesson = lessons.find((item) => item.slug === slugWithSkill);
        if (!existingLesson) {
          lessons.push(authoredLesson);
          addedLessons += 1;
        } else {
          existingLesson.is_free = authoredLesson.is_free;
          existingLesson.access_tier = authoredLesson.access_tier;
          // These route activities were added after the original European
          // Reading/Grammar/Vocabulary trio. Keep their authored payload in
          // sync when the generator is rerun.
          existingLesson.content_json = ['listening', 'speaking', 'writing'].includes(skill)
            ? authoredLesson.content_json
            : (existingLesson.content_json || {});
          // Keep Reading questions and every option in the target language.
          // Earlier generated German readings kept Spanish choices despite
          // German prompts; refreshing this narrow assessment payload also
          // prevents that mismatch whenever the generator is run again.
          if (skill === 'reading') {
            existingLesson.content_json.exercises = authoredLesson.content_json.exercises;
          }
          existingLesson.content_json.access_policy = authoredLesson.content_json.access_policy;
        }
      });
    });
  }
}

for (const [language, levelNames] of Object.entries(grammarNames)) {
  for (const [level, names] of Object.entries(levelNames)) {
    const orderedUnits = units
      .filter((unit) => unit.target_language === language && unit.level === level)
      .sort((a, b) => a.order_index - b.order_index)
      .slice(0, 12);
    orderedUnits.forEach((unit, index) => {
      const lesson = lessons.find((row) => row.target_language === language && row.level === level && row.unit_slug === unit.slug && row.skill === 'grammar');
      if (!lesson) return;
      lesson.content_json = lesson.content_json || {};
      // B1 was the remaining route that still displayed the cultural-unit
      // name followed by “grammar”. Use its authored grammar syllabus name
      // as the learner-facing lesson title, just like every other level.
      if (level === 'B1') {
        const name = names[index] || unit.title;
        lesson.title = name;
        lesson.description = `Tema gramatical: ${name}.`;
        lesson.content_json.mission = `Estudia ${name} y úsalo con precisión en contexto.`;
        lesson.content_json.extra = lesson.content_json.extra || {};
        lesson.content_json.extra.grammarProfile = {
          ...(lesson.content_json.extra.grammarProfile || {}),
          name,
          definition: `Práctica guiada de ${name}.`,
          function: 'Usar la estructura con precisión en contextos cotidianos.'
        };
      }
      // Italian and Portuguese maintain their richer authoring profiles in
      // their dedicated curriculum builder. This pass only enriches German.
      if (language !== 'german') return;
      lesson.content_json.extra = lesson.content_json.extra || {};
      lesson.content_json.extra.grammarProfile = {
        ...(lesson.content_json.extra.grammarProfile || {}),
        name: names[index] || unit.title,
        definition: `Práctica guiada de ${names[index] || unit.title}.`,
        function: 'Usar la estructura con precisión en contextos cotidianos.',
        examples: lesson.content_json.extra.grammarProfile?.examples || []
      };
      if (language === 'german' && germanGrammarTopics[level]?.[index]) {
        const [name, definition, example] = germanGrammarTopics[level][index];
        lesson.title = name;
        lesson.description = `Tema gramatical: ${name}.`;
        lesson.content_json.mission = `Lerne ${name} und verwende die Struktur in einem eigenen Satz.`;
        lesson.content_json.grammar = definition;
        lesson.content_json.phrases = [example];
        lesson.content_json.extra.grammarProfile = {
          name,
          definition,
          structure: example,
          function: 'Die Struktur in einer Alltagssituation korrekt verwenden.',
          examples: [example]
        };
      }
    });
  }
}
fs.writeFileSync(lessonsPath, `${JSON.stringify(lessons, null, 2)}\n`, 'utf8');
fs.writeFileSync(unitsPath, `${JSON.stringify(units, null, 2)}\n`, 'utf8');
console.log(`Added ${addedUnits} units and ${addedLessons} lessons.`);
